examples.code:
fs = 128;
n = 0:255;
t = n/fs;
x = sin(2*pi*16*t) + 0.5*sin(2*pi*40*t + 0.3) + 0.1*sin(1000*n.^2);
y = [zeros(1,2) x(1:end-2)];
[c, f] = cpsd(x, y, 64, 32, 128, fs);
k = find(f == 16);
fprintf('%d points\n', numel(c));
fprintf('angle at 16 Hz: %.4f rad\n', angle(c(k)));
fprintf('delay times frequency: %.4f rad\n', 2*pi*16*2/fs);

fs = 128;
n = 0:255;
t = n/fs;
x = sin(2*pi*16*t) + 0.5*sin(2*pi*40*t + 0.3) + 0.1*sin(1000*n.^2);
y = filter([1 0.5], 1, x) + 0.3*sin(2*pi*28*t);
[c, f] = mscohere(x, y, 64, 32, 128, fs);
fprintf('coherence at 16 Hz: %.3f\n', c(f == 16));
fprintf('coherence at 28 Hz: %.3f\n', c(f == 28));

